02-file-permissions-chmod-chown:
const fs = require('fs');
const path = require('path');

/**
 * File Permissions Controller
 * Demonstrates chmod and chown operations
 */

// Simulated file database for demo
const fileDatabase = {
  'document.txt': { owner: 'alice', group: 'staff', mode: 0o644 },
  'script.sh': { owner: 'bob', group: 'admin', mode: 0o755 },
  'config.json': { owner: 'root', group: 'root', mode: 0o600 },
  'data.csv': { owner: 'alice', group: 'staff', mode: 0o640 }
};

/**
 * Get module information
 * @returns {Object} Module description and purpose
 */
function getInfo() {
  return {
    name: 'File Permissions (chmod, chown)',
    description: 'Learn how to manage file ownership and permissions in Linux',
    topics: ['chmod - Change mode (permissions)', 'chown - Change owner', 'File permission bits'],
    importance: 'Critical for system security and file access control',
    commands_covered: ['chmod', 'chown', 'ls -l', 'stat']
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['changePermissions', 'changeOwnership', 'getFilePermissions'],
    total_objects: Object.keys(fileDatabase).length
  };
}

/**
 * Get file permissions in both decimal and symbolic notation
 * @param {string} filename - The file to check
 * @returns {Object} File permissions information
 */
function getFilePermissions(filename) {
  try {
    if (!fileDatabase[filename]) {
      throw new Error(`File not found: ${filename}`);
    }

    const file = fileDatabase[filename];
    const mode = file.mode;

    // Convert octal to binary and extract permission bits
    const owner = (mode >> 6) & 7;
    const group = (mode >> 3) & 7;
    const others = mode & 7;

    const toSymbolic = (bits) => {
      const r = (bits & 4) ? 'r' : '-';
      const w = (bits & 2) ? 'w' : '-';
      const x = (bits & 1) ? 'x' : '-';
      return r + w + x;
    };

    return {
      filename,
      owner: file.owner,
      group: file.group,
      decimal: mode.toString(),
      octal: '0o' + mode.toString(8),
      symbolic: toSymbolic(owner) + toSymbolic(group) + toSymbolic(others),
      permissions: {
        owner: { read: !!(owner & 4), write: !!(owner & 2), execute: !!(owner & 1) },
        group: { read: !!(group & 4), write: !!(group & 2), execute: !!(group & 1) },
        others: { read: !!(others & 4), write: !!(others & 2), execute: !!(others & 1) }
      }
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Change file permissions (chmod simulation)
 * @param {string} filename - File to modify
 * @param {string|number} mode - New permissions (octal string or number)
 * @returns {Object} Result of chmod operation
 */
function changePermissions(filename, mode) {
  try {
    if (!fileDatabase[filename]) {
      throw new Error(`File not found: ${filename}`);
    }

    const numMode = typeof mode === 'string' ? parseInt(mode, 8) : mode;
    const oldMode = fileDatabase[filename].mode;
    fileDatabase[filename].mode = numMode;

    return {
      success: true,
      filename,
      previous: '0o' + oldMode.toString(8),
      new: '0o' + numMode.toString(8),
      message: `Permissions changed successfully`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Change file ownership (chown simulation)
 * @param {string} filename - File to modify
 * @param {string} newOwner - New owner username
 * @param {string} newGroup - New group name
 * @returns {Object} Result of chown operation
 */
function changeOwnership(filename, newOwner, newGroup) {
  try {
    if (!fileDatabase[filename]) {
      throw new Error(`File not found: ${filename}`);
    }

    const file = fileDatabase[filename];
    const previousOwner = file.owner;
    const previousGroup = file.group;

    if (newOwner) file.owner = newOwner;
    if (newGroup) file.group = newGroup;

    return {
      success: true,
      filename,
      previous: { owner: previousOwner, group: previousGroup },
      new: { owner: file.owner, group: file.group },
      message: `Ownership changed successfully`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * List all files with their permissions (ls -l simulation)
 * @returns {Array} All files with permissions
 */
function listFilesWithPermissions() {
  return Object.entries(fileDatabase).map(([filename, file]) => {
    const mode = file.mode;
    const owner = (mode >> 6) & 7;
    const group = (mode >> 3) & 7;
    const others = mode & 7;

    const toSymbolic = (bits) => {
      const r = (bits & 4) ? 'r' : '-';
      const w = (bits & 2) ? 'w' : '-';
      const x = (bits & 1) ? 'x' : '-';
      return r + w + x;
    };

    return {
      filename,
      symbolic: toSymbolic(owner) + toSymbolic(group) + toSymbolic(others),
      octal: '0o' + mode.toString(8),
      owner: file.owner,
      group: file.group,
      size: Math.floor(Math.random() * 10000) + 100
    };
  });
}

module.exports = {
  getInfo,
  getTest,
  getFilePermissions,
  changePermissions,
  changeOwnership,
  listFilesWithPermissions
};

03-process-management-ps-kill-htop:
/**
 * Process Management Controller
 * Demonstrates ps, kill, and process monitoring
 */

// Simulated process database
const processDatabase = {
  1001: { pid: 1001, name: 'nginx', user: 'www-data', cpu: 2.5, memory: 45, status: 'running' },
  1002: { pid: 1002, name: 'node-server', user: 'app', cpu: 15.2, memory: 320, status: 'running' },
  1003: { pid: 1003, name: 'mysql', user: 'mysql', cpu: 8.3, memory: 512, status: 'running' },
  1004: { pid: 1004, name: 'redis', user: 'redis', cpu: 1.2, memory: 128, status: 'running' },
  1005: { pid: 1005, name: 'python-worker', user: 'app', cpu: 12.8, memory: 256, status: 'sleeping' }
};

let nextPid = 1006;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Process Management (ps, kill, htop)',
    description: 'Monitor, list, and control system processes',
    topics: ['ps - List processes', 'kill - Send signals', 'Process states', 'CPU and memory monitoring'],
    importance: 'Essential for server management and troubleshooting',
    commands_covered: ['ps', 'ps aux', 'kill', 'killall', 'top', 'htop']
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['listProcesses', 'killProcess', 'getProcessDetails'],
    active_processes: Object.keys(processDatabase).length
  };
}

/**
 * List all processes with optional filtering
 * @param {Object} filters - Filter options
 * @returns {Array} Filtered process list
 */
function listProcesses(filters = {}) {
  try {
    let processes = Object.values(processDatabase);

    if (filters.user) {
      processes = processes.filter(p => p.user === filters.user);
    }
    if (filters.status) {
      processes = processes.filter(p => p.status === filters.status);
    }
    if (filters.minCpu) {
      processes = processes.filter(p => p.cpu >= filters.minCpu);
    }

    return processes
      .sort((a, b) => b.cpu - a.cpu)
      .map(p => ({
        PID: p.pid,
        command: p.name,
        USER: p.user,
        '%CPU': p.cpu.toFixed(1),
        '%MEM': (p.memory / 4096 * 100).toFixed(1),
        STAT: p.status === 'running' ? 'R' : 'S'
      }));
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get detailed information about a specific process
 * @param {number} pid - Process ID
 * @returns {Object} Process details
 */
function getProcessDetails(pid) {
  try {
    if (!processDatabase[pid]) {
      throw new Error(`Process ${pid} not found`);
    }

    const process = processDatabase[pid];
    return {
      PID: process.pid,
      name: process.name,
      user: process.user,
      cpu_usage: process.cpu + '%',
      memory_usage: process.memory + 'MB',
      status: process.status,
      uptime_seconds: Math.floor(Math.random() * 86400),
      threads: Math.floor(Math.random() * 20) + 1,
      nice: Math.floor(Math.random() * 20) - 10
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Kill (terminate) a process
 * @param {number} pid - Process ID to kill
 * @param {number} signal - Signal number (default: 15 for SIGTERM)
 * @returns {Object} Kill operation result
 */
function killProcess(pid, signal = 15) {
  try {
    if (!processDatabase[pid]) {
      throw new Error(`Process ${pid} not found`);
    }

    const process = processDatabase[pid];
    const signalNames = {
      9: 'SIGKILL (force kill)',
      15: 'SIGTERM (graceful termination)',
      2: 'SIGINT (interrupt)'
    };

    if (signal === 9) {
      delete processDatabase[pid];
      return {
        success: true,
        pid,
        signal: signalNames[signal],
        status: 'terminated',
        message: `Process ${process.name} (PID ${pid}) was forcefully terminated`
      };
    } else {
      processDatabase[pid].status = 'terminating';
      setTimeout(() => {
        if (processDatabase[pid]) {
          delete processDatabase[pid];
        }
      }, 2000);

      return {
        success: true,
        pid,
        signal: signalNames[signal],
        status: 'terminating',
        message: `Graceful termination signal sent to ${process.name}`
      };
    }
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Start a new process (simulation)
 * @param {string} name - Process name
 * @param {string} user - User to run as
 * @returns {Object} New process information
 */
function startProcess(name, user = 'app') {
  try {
    const pid = nextPid++;
    const newProcess = {
      pid,
      name,
      user,
      cpu: 0.1,
      memory: Math.floor(Math.random() * 100) + 50,
      status: 'running'
    };

    processDatabase[pid] = newProcess;

    return {
      success: true,
      pid,
      name,
      user,
      message: `Process ${name} started successfully`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get system-wide resource statistics
 * @returns {Object} System resource usage
 */
function getSystemStats() {
  const processes = Object.values(processDatabase);
  const totalCpuUsage = processes.reduce((sum, p) => sum + p.cpu, 0);
  const totalMemoryUsage = processes.reduce((sum, p) => sum + p.memory, 0);

  return {
    total_processes: processes.length,
    total_cpu_usage: totalCpuUsage.toFixed(1) + '%',
    total_memory_usage: totalMemoryUsage + 'MB',
    cpu_cores: 8,
    system_memory: '16384MB',
    cpu_load_average: [(Math.random() * 4).toFixed(2), (Math.random() * 4).toFixed(2), (Math.random() * 4).toFixed(2)]
  };
}

module.exports = {
  getInfo,
  getTest,
  listProcesses,
  getProcessDetails,
  killProcess,
  startProcess,
  getSystemStats
};

04-ssh-keys-config-tunneling:
const crypto = require('crypto');

/**
 * SSH Keys and Tunneling Controller
 * Demonstrates SSH key generation, management, and tunneling
 */

// Simulated SSH keys database
const sshKeysDatabase = {
  'default': {
    name: 'default',
    type: 'ed25519',
    created: '2024-01-15',
    fingerprint: 'SHA256:abcd1234efgh5678ijkl9012mnop3456',
    public_key: 'ssh-ed25519 AAAAC3NzaC1lZDI1NTE5...',
    passphrase_protected: true
  },
  'github': {
    name: 'github',
    type: 'ed25519',
    created: '2024-02-20',
    fingerprint: 'SHA256:xyz1234abc5678def9012ghi3456jk',
    public_key: 'ssh-ed25519 AAAAC3NzaC1lZDI1NTE5...',
    passphrase_protected: false
  }
};

const sshConfigDatabase = {
  'prod-server': {
    host: 'prod.example.com',
    user: 'deploy',
    port: 22,
    identity_file: '~/.ssh/prod-key',
    strict_host_key_checking: 'accept-new'
  },
  'dev-server': {
    host: 'dev.example.com',
    user: 'developer',
    port: 2222,
    identity_file: '~/.ssh/github'
  }
};

const activeForwards = {};
let forwardId = 1;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'SSH Keys, Config & Tunneling',
    description: 'Generate, manage SSH keys and establish secure tunnels',
    topics: [
      'SSH key generation (RSA, Ed25519)',
      'SSH config file management',
      'Port forwarding and tunneling',
      'SSH host key verification'
    ],
    importance: 'Critical for secure remote access and server administration',
    commands_covered: ['ssh-keygen', 'ssh-copy-id', 'ssh -L', 'ssh -D', 'ssh-config']
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['listKeys', 'generateKey', 'createTunnel'],
    managed_keys: Object.keys(sshKeysDatabase).length,
    ssh_configs: Object.keys(sshConfigDatabase).length
  };
}

/**
 * List all SSH keys
 * @returns {Array} SSH keys list
 */
function listKeys() {
  try {
    return Object.values(sshKeysDatabase).map(key => ({
      name: key.name,
      type: key.type,
      fingerprint: key.fingerprint,
      created: key.created,
      passphrase_protected: key.passphrase_protected,
      bit_length: key.type === 'rsa' ? 4096 : 256
    }));
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Generate a new SSH key pair
 * @param {string} keyName - Name for the key
 * @param {string} keyType - Type: 'rsa' or 'ed25519'
 * @param {boolean} withPassphrase - Whether to add passphrase protection
 * @returns {Object} Generated key information
 */
function generateKey(keyName, keyType = 'ed25519', withPassphrase = true) {
  try {
    if (sshKeysDatabase[keyName]) {
      throw new Error(`Key '${keyName}' already exists`);
    }

    if (!['rsa', 'ed25519'].includes(keyType)) {
      throw new Error(`Invalid key type: ${keyType}`);
    }

    // Simulate key generation
    const publicKey = `ssh-${keyType} AAAA${crypto.randomBytes(20).toString('hex').substring(0, 40)}...`;
    const fingerprint = 'SHA256:' + crypto.randomBytes(32).toString('hex').substring(0, 32);

    sshKeysDatabase[keyName] = {
      name: keyName,
      type: keyType,
      created: new Date().toISOString().split('T')[0],
      fingerprint: fingerprint,
      public_key: publicKey,
      passphrase_protected: withPassphrase
    };

    return {
      success: true,
      keyName,
      keyType,
      fingerprint,
      message: `SSH key '${keyName}' generated successfully`,
      save_location: `~/.ssh/${keyName}`,
      public_key_location: `~/.ssh/${keyName}.pub`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Create SSH port forward (tunnel)
 * @param {string} localPort - Local port
 * @param {string} remoteHost - Remote host
 * @param {string} remotePort - Remote port
 * @param {string} sshConfig - SSH config name
 * @returns {Object} Forward information
 */
function createTunnel(localPort, remoteHost, remotePort, sshConfig) {
  try {
    if (!sshConfigDatabase[sshConfig]) {
      throw new Error(`SSH config '${sshConfig}' not found`);
    }

    const fwdId = forwardId++;
    const config = sshConfigDatabase[sshConfig];

    activeForwards[fwdId] = {
      id: fwdId,
      local_port: localPort,
      remote_host: remoteHost,
      remote_port: remotePort,
      ssh_config: sshConfig,
      status: 'active',
      established: new Date().toISOString()
    };

    return {
      success: true,
      forward_id: fwdId,
      status: 'established',
      local_address: `localhost:${localPort}`,
      remote_address: `${remoteHost}:${remotePort}`,
      via: `${config.user}@${config.host}:${config.port}`,
      command: `ssh -L ${localPort}:${remoteHost}:${remotePort} ${sshConfig}`,
      message: 'Port forward established successfully'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * List active SSH tunnels
 * @returns {Array} Active tunnels
 */
function listActiveTunnels() {
  return Object.values(activeForwards).map(fwd => ({
    id: fwd.id,
    local_port: fwd.local_port,
    remote: `${fwd.remote_host}:${fwd.remote_port}`,
    via: fwd.ssh_config,
    status: fwd.status,
    uptime: Math.floor(Math.random() * 3600) + 's'
  }));
}

/**
 * Close SSH tunnel
 * @param {number} forwardId - Forward tunnel ID
 * @returns {Object} Close result
 */
function closeTunnel(forwardId) {
  try {
    if (!activeForwards[forwardId]) {
      throw new Error(`Tunnel ${forwardId} not found`);
    }

    const fwd = activeForwards[forwardId];
    delete activeForwards[forwardId];

    return {
      success: true,
      forward_id: forwardId,
      message: `Tunnel closed: localhost:${fwd.local_port} -> ${fwd.remote_host}:${fwd.remote_port}`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Retrieve SSH config
 * @param {string} configName - Config name
 * @returns {Object} SSH config details
 */
function getSSHConfig(configName) {
  try {
    if (!sshConfigDatabase[configName]) {
      throw new Error(`SSH config '${configName}' not found`);
    }

    return sshConfigDatabase[configName];
  } catch (error) {
    return { error: error.message };
  }
}

module.exports = {
  getInfo,
  getTest,
  listKeys,
  generateKey,
  createTunnel,
  closeTunnel,
  listActiveTunnels,
  getSSHConfig
};

05-cron-syntax:
/**
 * Cron Syntax Controller
 * Demonstrates cron job scheduling and syntax validation
 */

// Simulated cron jobs database
const cronJobsDatabase = {
  'backup-daily': {
    id: 'backup-daily',
    schedule: '0 2 * * *',
    command: '/scripts/backup.sh',
    description: 'Daily backup at 2 AM',
    enabled: true,
    last_run: '2024-03-30 02:00:00',
    status: 'completed'
  },
  'cleanup-logs': {
    id: 'cleanup-logs',
    schedule: '0 */6 * * *',
    command: 'find /logs -mtime +30 -delete',
    description: 'Cleanup logs every 6 hours',
    enabled: true,
    last_run: '2024-03-31 00:00:00',
    status: 'running'
  },
  'health-check': {
    id: 'health-check',
    schedule: '*/5 * * * *',
    command: '/scripts/health-check.sh',
    description: 'Health check every 5 minutes',
    enabled: true,
    last_run: '2024-03-31 10:35:00',
    status: 'completed'
  }
};

let jobCounter = 3;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Cron Syntax and Scheduling',
    description: 'Understanding and managing cron jobs for task automation',
    topics: [
      'Cron expression format (minute hour day month day-of-week)',
      'Special characters: * ? - , /',
      'Common cron patterns',
      'Cron scheduling best practices'
    ],
    importance: 'Essential for automated system maintenance and tasks',
    cron_format: '┌── minute (0-59)\n│ ┌── hour (0-23)\n│ │ ┌── day of month (1-31)\n│ │ │ ┌── month (1-12)\n│ │ │ │ ┌── day of week (0-7, 0 and 7 = Sunday)\n\n* * * * * <command>'
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['listJobs', 'validateCronjobs', 'createCronjob'],
    active_jobs: Object.values(cronJobsDatabase).filter(j => j.enabled).length
  };
}

/**
 * Validate cron expression syntax
 * @param {string} expression - Cron expression to validate
 * @returns {Object} Validation result
 */
function validateCronExpression(expression) {
  try {
    const parts = expression.trim().split(/\s+/);

    if (parts.length !== 5) {
      throw new Error('Cron expression must have exactly 5 fields (minute hour day month day-of-week)');
    }

    const [minute, hour, day, month, dayOfWeek] = parts;
    const ranges = {
      minute: [0, 59],
      hour: [0, 23],
      day: [1, 31],
      month: [1, 12],
      dayOfWeek: [0, 7]
    };

    const validateField = (field, [min, max]) => {
      if (field === '*' || field === '?') return true;
      if (field.includes(',')) {
        return field.split(',').every(f => validateField(f.trim(), [min, max]));
      }
      if (field.includes('-')) {
        const [start, end] = field.split('-').map(Number);
        return start >= min && end <= max && start <= end;
      }
      if (field.includes('/')) {
        return true; // Simplified validation
      }
      const num = Number(field);
      return !isNaN(num) && num >= min && num <= max;
    };

    const validations = {
      minute: validateField(minute, ranges.minute),
      hour: validateField(hour, ranges.hour),
      day: validateField(day, ranges.day),
      month: validateField(month, ranges.month),
      dayOfWeek: validateField(dayOfWeek, ranges.dayOfWeek)
    };

    const allValid = Object.values(validations).every(v => v);

    return {
      valid: allValid,
      expression,
      field_validation: validations,
      description: describeExpression(expression)
    };
  } catch (error) {
    return { valid: false, error: error.message };
  }
}

/**
 * Generate human-readable description of cron expression
 * @param {string} expression - Cron expression
 * @returns {string} Description
 */
function describeExpression(expression) {
  const parts = expression.split(/\s+/);
  if (parts.length !== 5) return 'Invalid expression';

  const [minute, hour, day, month] = parts;

  const descriptions = [];
  if (minute !== '*') descriptions.push(`at minute ${minute}`);
  if (hour !== '*') descriptions.push(`past hour ${hour}`);
  if (day !== '*' && day !== '?') descriptions.push(`on day ${day}`);
  if (month !== '*') descriptions.push(`of month ${month}`);

  return descriptions.length > 0 ? descriptions.join(' ') : 'Every minute';
}

/**
 * List all cron jobs
 * @param {Object} filters - Filter options
 * @returns {Array} Cron jobs list
 */
function listCronJobs(filters = {}) {
  let jobs = Object.values(cronJobsDatabase);

  if (filters.enabled !== undefined) {
    jobs = jobs.filter(j => j.enabled === filters.enabled);
  }
  if (filters.status) {
    jobs = jobs.filter(j => j.status === filters.status);
  }

  return jobs.map(job => ({
    id: job.id,
    schedule: job.schedule,
    description: job.description,
    command: job.command,
    enabled: job.enabled,
    last_run: job.last_run,
    status: job.status
  }));
}

/**
 * Create a new cron job
 * @param {string} description - Job description
 * @param {string} schedule - Cron expression
 * @param {string} command - Command to execute
 * @returns {Object} Created job information
 */
function createCronJob(description, schedule, command) {
  try {
    const validation = validateCronExpression(schedule);
    if (!validation.valid) {
      throw new Error(`Invalid cron expression: ${validation.error}`);
    }

    const jobId = `job-${++jobCounter}`;
    cronJobsDatabase[jobId] = {
      id: jobId,
      schedule,
      command,
      description,
      enabled: true,
      last_run: null,
      status: 'scheduled'
    };

    return {
      success: true,
      jobId,
      schedule,
      description,
      message: 'Cron job created successfully'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get common cron patterns
 * @returns {Array} Common patterns
 */
function getCommonPatterns() {
  return [
    { expression: '0 0 * * *', description: 'Every day at midnight', use_case: 'Daily cleanup' },
    { expression: '0 */6 * * *', description: 'Every 6 hours', use_case: 'Regular backups' },
    { expression: '*/5 * * * *', description: 'Every 5 minutes', use_case: 'Health checks' },
    { expression: '0 0 1 * *', description: 'First day of month', use_case: 'Monthly reports' },
    { expression: '0 9 * * 1', description: 'Every Monday at 9 AM', use_case: 'Weekly sync' },
