/**
 * Systemd Service Management Controller
 * Demonstrates systemd service operations and management
 */

// Simulated systemd services database
const servicesDatabase = {
  'nginx': {
    name: 'nginx',
    type: 'service',
    description: 'NGINX HTTP Server',
