ExecStart=/usr/bin/python3 /opt/app/main.py
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target`
};

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Systemd Service Management',
    description: 'Control and manage systemd services for applications',
    topics: [
      'Service unit files',
      'Service states (active, inactive, failed)',
      'Enable/disable services',
      'Restart and reload services',
      'Check service status and logs'
    ],
    importance: 'Critical for managing server applications and daemons',
    commands_covered: ['systemctl start/stop/restart', 'systemctl enable/disable', 'systemctl status', 'journalctl']
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['listServices', 'startService', 'getServiceStatus'],
    total_services: Object.keys(servicesDatabase).length,
    active_services: Object.values(servicesDatabase).filter(s => s.status === 'active').length
  };
}

/**
 * List all systemd services
 * @param {Object} filters - Filter options
 * @returns {Array} Services list
 */
function listServices(filters = {}) {
  let services = Object.values(servicesDatabase);

  if (filters.status) {
    services = services.filter(s => s.status === filters.status);
  }
  if (filters.enabled !== undefined) {
    services = services.filter(s => s.enabled === filters.enabled);
  }
  if (filters.loaded !== undefined) {
    services = services.filter(s => s.loaded === filters.loaded);
  }

  return services.map(s => ({
    name: s.name,
    description: s.description,
    loaded: s.loaded,
    active: s.status === 'active' ? 'active' : 'inactive',
    enabled: s.enabled ? 'enabled' : 'disabled',
    sub_state: s.sub_state
  }));
}

/**
 * Get detailed service status
 * @param {string} serviceName - Service name
 * @returns {Object} Service details
 */
function getServiceStatus(serviceName) {
  try {
    if (!servicesDatabase[serviceName]) {
      throw new Error(`Service '${serviceName}' not found`);
    }

    const service = servicesDatabase[serviceName];
    const uptimeSeconds = service.uptime_seconds;
    const days = Math.floor(uptimeSeconds / 86400);
    const hours = Math.floor((uptimeSeconds % 86400) / 3600);
    const minutes = Math.floor((uptimeSeconds % 3600) / 60);

    return {
      name: service.name,
      description: service.description,
      loaded: service.loaded,
      active_state: service.active_state,
      sub_state: service.sub_state,
      enabled: service.enabled ? 'enabled' : 'disabled',
      uptime: `${days}d ${hours}h ${minutes}m`,
      memory_usage: `${service.memory_mb}MB`,
      cpu_usage: `${service.cpu_percent}%`,
      can_reload: true,
      can_restart: true
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Start a systemd service
 * @param {string} serviceName - Service name
 * @returns {Object} Start result
 */
function startService(serviceName) {
  try {
    if (!servicesDatabase[serviceName]) {
      throw new Error(`Service '${serviceName}' not found`);
    }

    const service = servicesDatabase[serviceName];
    if (service.status === 'active') {
      return { success: false, message: `Service '${serviceName}' is already running` };
    }

    service.status = 'active';
    service.active_state = 'active';
    service.sub_state = 'running';
    service.uptime_seconds = 0;
    service.memory_mb = Math.floor(Math.random() * 200) + 50;

    return {
      success: true,
      service: serviceName,
      action: 'started',
      message: `Service '${serviceName}' started successfully`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Stop a systemd service
 * @param {string} serviceName - Service name
 * @returns {Object} Stop result
 */
function stopService(serviceName) {
  try {
    if (!servicesDatabase[serviceName]) {
      throw new Error(`Service '${serviceName}' not found`);
    }

    const service = servicesDatabase[serviceName];
    if (service.status === 'inactive') {
      return { success: false, message: `Service '${serviceName}' is already stopped` };
    }

    service.status = 'inactive';
    service.active_state = 'inactive';
    service.sub_state = 'dead';
    service.uptime_seconds = 0;
    service.memory_mb = 0;
    service.cpu_percent = 0;

    return {
      success: true,
      service: serviceName,
      action: 'stopped',
      message: `Service '${serviceName}' stopped successfully`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Restart a systemd service
 * @param {string} serviceName - Service name
 * @returns {Object} Restart result
 */
function restartService(serviceName) {
  try {
    if (!servicesDatabase[serviceName]) {
      throw new Error(`Service '${serviceName}' not found`);
    }

    const service = servicesDatabase[serviceName];
    service.uptime_seconds = 0;
    service.memory_mb = Math.floor(Math.random() * 200) + 50;
    service.status = 'active';
    service.active_state = 'active';
    service.sub_state = 'running';

    return {
      success: true,
      service: serviceName,
      action: 'restarted',
      message: `Service '${serviceName}' restarted successfully`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Enable or disable a service
 * @param {string} serviceName - Service name
 * @param {boolean} enable - Enable (true) or disable (false)
 * @returns {Object} Result
 */
function setServiceEnabled(serviceName, enable = true) {
  try {
    if (!servicesDatabase[serviceName]) {
      throw new Error(`Service '${serviceName}' not found`);
    }

    servicesDatabase[serviceName].enabled = enable;

    return {
      success: true,
      service: serviceName,
      action: enable ? 'enabled' : 'disabled',
      message: `Service '${serviceName}' ${enable ? 'enabled' : 'disabled'} for auto-start`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get service unit file template
 * @param {string} templateName - Template name
 * @returns {Object} Template content
 */
function getServiceTemplate(templateName) {
  try {
    if (!serviceTemplates[templateName]) {
      throw new Error(`Template '${templateName}' not found`);
    }

    return {
      name: templateName,
      content: serviceTemplates[templateName],
      location: `/etc/systemd/system/${templateName}.service`
    };
  } catch (error) {
    return { error: error.message };
  }
}

module.exports = {
  getInfo,
  getTest,
  listServices,
  getServiceStatus,
  startService,
  stopService,
  restartService,
  setServiceEnabled,
  getServiceTemplate
};

