    status: 'ready',
    tests: ['getCPUMetrics', 'getMemoryMetrics', 'getDiskUsage'],
    monitoring_enabled: true
  };
}

/**
 * Get CPU metrics
 * @returns {Object} CPU usage information
 */
function getCPUMetrics() {
  try {
    const cpu = systemMetricsDatabase.cpu;
    const [load1, load5, load15] = cpu.load_average;
    const utilization = (load1 / cpu.cores * 100).toFixed(1);

    return {
      cpu_cores: cpu.cores,
      current_usage: `${cpu.usage_percent}%`,
      load_average: {
        one_minute: load1.toFixed(2),
        five_minutes: load5.toFixed(2),
        fifteen_minutes: load15.toFixed(2)
      },
      utilization_percent: `${utilization}%`,
      temperature_celsius: cpu.temp_celsius,
      frequency_ghz: cpu.frequency_ghz,
      model: cpu.model,
      health_status: cpu.temp_celsius > 80 ? 'warning' : cpu.temp_celsius > 90 ? 'critical' : 'normal'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get memory metrics
 * @returns {Object} Memory usage information
 */
function getMemoryMetrics() {
  try {
    const mem = systemMetricsDatabase.memory;

    return {
      total_memory_gb: mem.total_gb,
      used_memory_gb: mem.used_gb.toFixed(2),
      free_memory_gb: mem.free_gb.toFixed(2),
      available_memory_gb: (mem.free_gb + mem.cache_gb).toFixed(2),
      usage_percent: mem.percent_used.toFixed(2),
      cache_gb: mem.cache_gb.toFixed(2),
      swap_total_gb: mem.swap_total_gb,
      swap_used_gb: mem.swap_used_gb.toFixed(2),
      swap_percent: ((mem.swap_used_gb / mem.swap_total_gb) * 100).toFixed(2),
      memory_pressure: mem.percent_used > 80 ? 'high' : mem.percent_used > 60 ? 'moderate' : 'low'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get disk usage information
 * @param {string} mountPoint - Mount point filter (optional)
 * @returns {Object|Array} Disk information
 */
function getDiskUsage(mountPoint = null) {
  try {
    const disks = systemMetricsDatabase.disks;

    if (mountPoint && disks[mountPoint]) {
      const disk = disks[mountPoint];
      return {
        mount_point: disk.mount_point,
        filesystem: disk.filesystem,
        total_gb: disk.size_gb,
        used_gb: disk.used_gb.toFixed(2),
        free_gb: disk.free_gb.toFixed(2),
        usage_percent: disk.percent_used.toFixed(2),
        inodes_used_percent: (Math.random() * 50).toFixed(2),
        health_status: disk.percent_used > 90 ? 'critical' : disk.percent_used > 75 ? 'warning' : 'ok'
      };
    }

    return Object.values(disks).map(disk => ({
      mount_point: disk.mount_point,
      filesystem: disk.filesystem,
      total_gb: disk.size_gb,
      used_gb: disk.used_gb.toFixed(2),
      free_gb: disk.free_gb.toFixed(2),
      usage_percent: disk.percent_used.toFixed(2),
      health: disk.percent_used > 90 ? 'critical' : disk.percent_used > 75 ? 'warning' : 'ok'
    }));
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get top processes by resource usage
 * @param {string} sortBy - Sort criteria: 'cpu' or 'memory'
 * @param {number} limit - Number of top processes
 * @returns {Array} Top processes
 */
function getTopProcesses(sortBy = 'cpu', limit = 5) {
  try {
    let processes = [...systemMetricsDatabase.processes];

    if (sortBy === 'cpu') {
      processes.sort((a, b) => b.cpu_percent - a.cpu_percent);
    } else if (sortBy === 'memory') {
      processes.sort((a, b) => b.memory_percent - a.memory_percent);
    }

    return processes.slice(0, limit).map(p => ({
      PID: p.pid,
      command: p.name,
      CPU: `${p.cpu_percent}%`,
      MEM: `${p.memory_percent}%`,
      resource_intensive: p.cpu_percent > 10 || p.memory_percent > 10
    }));
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get I/O statistics
 * @returns {Object} I/O metrics
 */
function getIOStatistics() {
  try {
    return {
      disk_read_mb_s: (Math.random() * 50).toFixed(2),
      disk_write_mb_s: (Math.random() * 30).toFixed(2),
      disk_io_utilization: (Math.random() * 80).toFixed(1),
      io_wait_percent: (Math.random() * 20).toFixed(1),
      avg_queue_length: (Math.random() * 5).toFixed(2),
      iostat_available: true
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get system health status
 * @returns {Object} Overall system health
 */
function getSystemHealth() {
  try {
    const cpu = getCPUMetrics();
    const mem = getMemoryMetrics();
    const disks = getDiskUsage();

    const issues = [];
    if (parseFloat(cpu.temperature_celsius) > 85) issues.push('High CPU temperature');
    if (parseFloat(mem.usage_percent) > 80) issues.push('High memory usage');
    if (Array.isArray(disks) && disks.some(d => d.health === 'critical')) issues.push('Disk space critical');

    const overallHealth = issues.length === 0 ? 'healthy' : issues.length <= 1 ? 'warning' : 'critical';

    return {
      overall_health: overallHealth,
      cpu_health: cpu.health_status,
      memory_pressure: mem.memory_pressure,
      disk_health: Array.isArray(disks) ? (disks.every(d => d.health === 'ok') ? 'healthy' : 'warning') : 'ok',
      issues,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return { error: error.message };
  }
}

module.exports = {
  getInfo,
  getTest,
  getCPUMetrics,
  getMemoryMetrics,
  getDiskUsage,
  getTopProcesses,
  getIOStatistics,
  getSystemHealth
};

