/**
 * Firewall (UFW) Management Controller
 * Demonstrates firewall rules and port management
 */

// Simulated firewall rules database
const firewallRulesDatabase = [
  { id: 1, port: 22, protocol: 'tcp', direction: 'in', action: 'allow', description: 'SSH' },
  { id: 2, port: 80, protocol: 'tcp', direction: 'in', action: 'allow', description: 'HTTP' },
  { id: 3, port: 443, protocol: 'tcp', direction: 'in', action: 'allow', description: 'HTTPS' },
  { id: 4, port: 3306, protocol: 'tcp', direction: 'in', action: 'deny', description: 'MySQL (denied)' },
  { id: 5, port: 5432, protocol: 'tcp', direction: 'in', action: 'allow', source: '192.168.1.0/24', description: 'PostgreSQL (local network only)' }
];

const blockedIPs = [
  { ip: '192.168.1.100', reason: 'Repeated brute force attempts', blocked_since: '2024-03-20' },
  { ip: '10.0.0.50', reason: 'Malicious activity detected', blocked_since: '2024-03-25' }
];

let ruleIdCounter = 5;
let firewallEnabled = true;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Firewall (UFW) Basics',
    description: 'Manage network firewall rules and IP blocking',
    topics: [
      'UFW (Uncomplicated Firewall) basics',
      'Inbound and outbound rules',
      'Port filtering',
      'IP blocking and whitelisting',
      'Default policies',
      'Application profiles'
    ],
    importance: 'Critical for network security and access control',
    commands_covered: ['ufw enable', 'ufw allow', 'ufw deny', 'ufw status', 'ufw reset']
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['getFirewallStatus', 'addRule', 'removeRule'],
    enabled: firewallEnabled,
    total_rules: firewallRulesDatabase.length,
    blocked_ips: blockedIPs.length
  };
}

/**
 * Get firewall status
 * @returns {Object} Firewall status information
 */
function getFirewallStatus() {
  try {
    return {
      status: firewallEnabled ? 'active' : 'inactive',
      enabled: firewallEnabled,
      default_incoming: 'deny',
      default_outgoing: 'allow',
      default_routed: 'disabled',
      total_rules: firewallRulesDatabase.length,
      total_blocked_ips: blockedIPs.length,
      logging: 'low',
      logging_level: 'medium'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * List firewall rules
 * @param {Object} filters - Filter options
 * @returns {Array} Firewall rules
 */
function listRules(filters = {}) {
  try {
    let rules = [...firewallRulesDatabase];

    if (filters.port) {
      rules = rules.filter(r => r.port === filters.port);
    }
    if (filters.protocol) {
      rules = rules.filter(r => r.protocol === filters.protocol);
    }
    if (filters.action) {
      rules = rules.filter(r => r.action === filters.action);
    }
    if (filters.direction) {
      rules = rules.filter(r => r.direction === filters.direction);
    }

    return rules.map(rule => ({
      id: rule.id,
      port: rule.port,
      protocol: rule.protocol.toUpperCase(),
      direction: rule.direction,
      action: rule.action.toUpperCase(),
      source: rule.source || 'any',
      description: rule.description
    }));
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Add a firewall rule
 * @param {number} port - Port number
 * @param {string} protocol - Protocol (tcp/udp)
 * @param {string} action - Action (allow/deny)
 * @param {string} description - Rule description
 * @param {string} source - Source IP (optional)
 * @returns {Object} Add rule result
 */
function addRule(port, protocol = 'tcp', action = 'allow', description = '', source = null) {
  try {
    if (!firewallEnabled) {
      throw new Error('Firewall is disabled. Enable firewall first.');
    }

    if (port < 1 || port > 65535) {
      throw new Error('Port must be between 1 and 65535');
    }

    if (!['tcp', 'udp'].includes(protocol.toLowerCase())) {
      throw new Error('Protocol must be tcp or udp');
    }

    if (!['allow', 'deny'].includes(action.toLowerCase())) {
      throw new Error('Action must be allow or deny');
    }

    const newRule = {
      id: ++ruleIdCounter,
      port,
      protocol: protocol.toLowerCase(),
      direction: 'in',
      action: action.toLowerCase(),
      description: description || `Port ${port}/${protocol.toUpperCase()}`,
      ...(source && { source })
    };

    firewallRulesDatabase.push(newRule);

    return {
      success: true,
      rule_id: newRule.id,
      port,
      protocol: protocol.toUpperCase(),
      action: action.toUpperCase(),
      message: `Rule added: ${action.toUpperCase()} ${port}/${protocol.toUpperCase()}`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Remove a firewall rule
 * @param {number} ruleId - Rule ID
 * @returns {Object} Remove result
 */
function removeRule(ruleId) {
  try {
    const index = firewallRulesDatabase.findIndex(r => r.id === ruleId);
    if (index === -1) {
      throw new Error(`Rule ${ruleId} not found`);
    }

    const removed = firewallRulesDatabase[index];
    firewallRulesDatabase.splice(index, 1);

    return {
      success: true,
      rule_id: ruleId,
      removed_rule: `${removed.action.toUpperCase()} ${removed.port}/${removed.protocol.toUpperCase()}`,
      message: `Rule ${ruleId} removed successfully`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Block an IP address
 * @param {string} ip - IP address to block
 * @param {string} reason - Reason for blocking
 * @returns {Object} Block result
 */
function blockIP(ip, reason = '') {
  try {
    if (blockedIPs.find(b => b.ip === ip)) {
      throw new Error(`IP ${ip} is already blocked`);
    }

    blockedIPs.push({
      ip,
      reason: reason || 'Manually blocked',
      blocked_since: new Date().toISOString().split('T')[0]
    });

    return {
      success: true,
      ip,
      action: 'blocked',
      message: `IP address ${ip} has been blocked`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Unblock an IP address
 * @param {string} ip - IP address to unblock
 * @returns {Object} Unblock result
 */
function unblockIP(ip) {
  try {
    const index = blockedIPs.findIndex(b => b.ip === ip);
    if (index === -1) {
      throw new Error(`IP ${ip} is not blocked`);
    }

    blockedIPs.splice(index, 1);

    return {
      success: true,
      ip,
      action: 'unblocked',
      message: `IP address ${ip} has been unblocked`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * List blocked IP addresses
 * @returns {Array} Blocked IPs
 */
function listBlockedIPs() {
  return blockedIPs.map(b => ({
    ip: b.ip,
    reason: b.reason,
    blocked_since: b.blocked_since
  }));
}

/**
 * Enable or disable firewall
 * @param {boolean} enable - Enable (true) or disable (false)
 * @returns {Object} Result
 */
function setFirewallEnabled(enable = true) {
  try {
