const fs = require('fs');
const path = require('path');

/**
 * Log Management & Logrotate Controller
 * Demonstrates log rotation, archival, and cleanup
 */

// Simulated log files database
const logFilesDatabase = {
  '/var/log/nginx/access.log': {
    path: '/var/log/nginx/access.log',
    size_mb: 524,
    lines: 2500000,
    last_modified: '2024-03-31',
    retention_days: 30,
    compression: 'gzip'
  },
  '/var/log/nginx/error.log': {
    path: '/var/log/nginx/error.log',
    size_mb: 12,
    lines: 45000,
    last_modified: '2024-03-31',
    retention_days: 30,
    compression: 'gzip'
  },
  '/var/log/mysql/error.log': {
    path: '/var/log/mysql/error.log',
    size_mb: 8,
    lines: 15000,
    last_modified: '2024-03-30',
    retention_days: 60,
    compression: 'gzip'
  },
  '/var/log/auth.log': {
    path: '/var/log/auth.log',
    size_mb: 45,
    lines: 120000,
    last_modified: '2024-03-31',
    retention_days: 90,
    compression: 'gzip'
  }
};

const logRotationConfig = {
  nginx_access: {
    logfile: '/var/log/nginx/access.log',
    rotate: 14,
    size: '100M',
    daily: true,
    compress: true,
    delaycompress: true,
    missingok: true,
    notifempty: true,
    create: '0640 www-data www-data'
  }
};

const archivedLogs = [
  { filename: 'access.log-2024-03-30.gz', date: '2024-03-30', size_mb: 45, archived_at: '2024-03-31' },
  { filename: 'access.log-2024-03-29.gz', date: '2024-03-29', size_mb: 48, archived_at: '2024-03-30' },
  { filename: 'access.log-2024-03-28.gz', date: '2024-03-28', size_mb: 52, archived_at: '2024-03-29' }
];

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Log Management & Logrotate',
    description: 'Manage, rotate, compress, and archive log files efficiently',
    topics: [
      'Log rotation policies',
      'Log compression (gzip)',
      'Log retention and cleanup',
      'Logrotate configuration',
      'Log analysis and searching'
    ],
    importance: 'Critical for managing disk space and maintaining system health',
    commands_covered: ['logrotate', 'logrotate -f', 'gzip', 'gunzip', 'tar', 'find']
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['listLogFiles', 'rotateLog', 'getLogRotationStatus'],
    total_logs: Object.keys(logFilesDatabase).length,
    archived_logs: archivedLogs.length
  };
}

/**
 * List all log files
 * @param {Object} filters - Filter options
 * @returns {Array} Log files list
 */
function listLogFiles(filters = {}) {
  try {
    let logs = Object.values(logFilesDatabase);

    if (filters.minSize) {
      logs = logs.filter(l => l.size_mb >= filters.minSize);
    }
    if (filters.path) {
      logs = logs.filter(l => l.path.includes(filters.path));
    }

    return logs
      .sort((a, b) => b.size_mb - a.size_mb)
      .map(log => ({
        path: log.path,
        size_mb: log.size_mb.toFixed(2),
        lines: log.lines.toLocaleString(),
        last_modified: log.last_modified,
        retention_days: log.retention_days,
        compression: log.compression,
        needs_rotation: log.size_mb > 100
      }));
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get log file details
 * @param {string} logPath - Log file path
 * @returns {Object} Log file details
 */
function getLogFileDetails(logPath) {
  try {
    if (!logFilesDatabase[logPath]) {
      throw new Error(`Log file '${logPath}' not found`);
    }

    const log = logFilesDatabase[logPath];
    const rotationConfig = logRotationConfig['nginx_access']; // Generic config

    return {
      path: log.path,
      size_mb: log.size_mb.toFixed(2),
      lines: log.lines.toLocaleString(),
      last_modified: log.last_modified,
      daily_growth_mb: (Math.random() * 50).toFixed(2),
      days_until_rotation: Math.ceil((rotationConfig.size.replace('M', '') - log.size_mb) / (log.size_mb / 10)),
      retention_policy: {
        retention_days: log.retention_days,
        rotation_size: rotationConfig.size,
        compression: log.compression,
        keep_copies: rotationConfig.rotate
      },
      estimated_disk_usage: ((log.size_mb + log.size_mb * rotationConfig.rotate * 0.3) / 1024).toFixed(2) + ' GB'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Rotate a log file manually
 * @param {string} logPath - Log file path
 * @returns {Object} Rotation result
 */
function rotateLog(logPath) {
  try {
    if (!logFilesDatabase[logPath]) {
      throw new Error(`Log file '${logPath}' not found`);
    }

    const log = logFilesDatabase[logPath];
    const filename = path.basename(logPath);
    const today = new Date().toISOString().split('T')[0];

    // Create archived log entry
    const originalSize = log.size_mb;
    archivedLogs.unshift({
      filename: `${filename}-${today}.gz`,
      date: today,
      size_mb: (originalSize * 0.25).toFixed(2), // Simulated compression
      archived_at: today
    });

    // Reset current log
    log.size_mb = 0;
    log.lines = 0;
    log.last_modified = today;

    return {
      success: true,
      logfile: logPath,
      action: 'rotated',
      archived_as: `${filename}-${today}.gz`,
      original_size_mb: originalSize.toFixed(2),
      compressed_size_mb: (originalSize * 0.25).toFixed(2),
      compression_ratio: '75%',
      message: `Log file '${logPath}' rotated successfully`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get logrotate configuration
 * @param {string} serviceName - Service name
 * @returns {Object} Logrotate config
 */
function getLogrotateConfig(serviceName = 'nginx_access') {
  try {
    if (!logRotationConfig[serviceName]) {
      throw new Error(`Config for '${serviceName}' not found`);
    }

    const config = logRotationConfig[serviceName];
    return config;
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * List archived logs
 * @returns {Array} Archived logs
 */
function listArchivedLogs() {
  return archivedLogs.map(log => ({
    filename: log.filename,
    date: log.date,
    size_mb: log.size_mb.toFixed(2),
    archived_at: log.archived_at,
    age_days: Math.floor((new Date() - new Date(log.archived_at)) / (1000 * 60 * 60 * 24))
  }));
}

/**
 * Get log rotation status and statistics
 * @returns {Object} Status information
 */
function getLogRotationStatus() {
  try {
    const logs = Object.values(logFilesDatabase);
    const totalSize = logs.reduce((sum, log) => sum + log.size_mb, 0);
    const archiveSize = archivedLogs.reduce((sum, log) => sum + parseFloat(log.size_mb), 0);
    const needsRotation = logs.filter(log => log.size_mb > 100).length;

    return {
      total_active_logs: logs.length,
      total_active_size_mb: totalSize.toFixed(2),
      total_archived_mb: archiveSize.toFixed(2),
      logs_needing_rotation: needsRotation,
      archived_copies: archivedLogs.length,
      last_rotation: archivedLogs.length > 0 ? archivedLogs[0].archived_at : 'never',
      estimated_daily_growth_gb: (logs.reduce((sum, log) => sum + log.size_mb, 0) * 0.05 / 1024).toFixed(2),
      disk_space_could_save_gb: (archiveSize * 0.75 / 1024).toFixed(2)
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Clean up old archived logs
 * @param {number} olderThanDays - Delete logs older than this many days
 * @returns {Object} Cleanup result
 */
function cleanupOldLogs(olderThanDays = 30) {
  try {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - olderThanDays);

    const beforeCount = archivedLogs.length;
    const removed = [];

    for (let i = archivedLogs.length - 1; i >= 0; i--) {
      if (new Date(archivedLogs[i].archived_at) < cutoffDate) {
        removed.push(archivedLogs.splice(i, 1)[0]);
      }
    }

    const freedSpace = removed.reduce((sum, log) => sum + parseFloat(log.size_mb), 0);

    return {
      success: true,
      logs_deleted: removed.length,
      freed_space_mb: freedSpace.toFixed(2),
      before_count: beforeCount,
      after_count: archivedLogs.length,
      deleted_logs: removed.map(l => l.filename),
      message: `Deleted ${removed.length} archived logs older than ${olderThanDays} days`
    };
  } catch (error) {
    return { error: error.message };
  }
}

module.exports = {
  getInfo,
  getTest,
  listLogFiles,
  getLogFileDetails,
  rotateLog,
  getLogrotateConfig,
  listArchivedLogs,
  getLogRotationStatus,
  cleanupOldLogs
};

