      },
      port_mappings: container.port_mappings,
      namespaces_used: Object.keys(namespaces)
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get container resource statistics
 * @param {string} containerId - Container ID or name
 * @returns {Object} Resource statistics
 */
function getContainerStats(containerId) {
  try {
    const container = containersDatabase[containerId];
    if (!container) {
      throw new Error(`Container '${containerId}' not found`);
    }

    return {
      container_id: container.id,
      timestamp: new Date().toISOString(),
      memory: {
        usage_bytes: container.memory_usage_mb * 1024 * 1024,
        limit_bytes: container.memory_limit_mb * 1024 * 1024,
        percent: ((container.memory_usage_mb / container.memory_limit_mb) * 100).toFixed(1)
      },
      cpu: {
        usage_percent: container.cpu_usage_percent,
        limit_cores: parseFloat(container.cpu_limit),
        throttling: container.cpu_usage_percent > 80
      },
      io: {
        read_bytes: Math.floor(Math.random() * 1000000000),
        write_bytes: Math.floor(Math.random() * 500000000),
        read_ops: Math.floor(Math.random() * 50000),
        write_ops: Math.floor(Math.random() * 30000)
      },
      network: {
        rx_bytes: Math.floor(Math.random() * 5000000000),
        tx_bytes: Math.floor(Math.random() * 5000000000),
        rx_packets: Math.floor(Math.random() * 1000000),
        tx_packets: Math.floor(Math.random() * 1000000)
      }
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * List Linux namespaces
 * @param {string} type - Namespace type filter (optional)
 * @returns {Array} Namespaces list
 */
function listNamespaces(type = null) {
  try {
    let ns = Object.values(namespaces);

    if (type) {
      ns = ns.filter(n => n.type === type);
    }

    return ns.map(n => ({
      type: n.type,
      description: n.description,
      containers_using: n.containers_using,
      purpose: `Provides ${n.description.toLowerCase()}`
    }));
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get cgroups configuration
 * @returns {Object} Cgroups configuration
 */
function getCgroupsConfig() {
  try {
    return {
      cpu: {
        quota: cgroupsConfig.cpu_quota,
        period: cgroupsConfig.cpu_period,
        shares: 1024
      },
      memory: {
        limit_bytes: cgroupsConfig.memory_limit,
        soft_limit_bytes: cgroupsConfig.memory_soft_limit,
        swap_limit_bytes: cgroupsConfig.memory_limit
      },
      blkio: {
        weight: cgroupsConfig.blkio_weight
      },
      net: {
        priority: cgroupsConfig.net_priority
      },
      summary: 'Control groups allow limiting and prioritizing resource usage'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Control container (start/stop)
 * @param {string} containerId - Container ID
 * @param {string} action - Action: 'start' or 'stop'
 * @returns {Object} Control result
 */
function controlContainer(containerId, action = 'start') {
  try {
    if (!containersDatabase[containerId]) {
      throw new Error(`Container '${containerId}' not found`);
    }

    const container = containersDatabase[containerId];

    if (action === 'start') {
      if (container.status === 'running') {
        throw new Error(`Container '${containerId}' is already running`);
      }
      container.status = 'running';
      container.uptime_seconds = 0;
    } else if (action === 'stop') {
      if (container.status === 'exited') {
        throw new Error(`Container '${containerId}' is already stopped`);
      }
      container.status = 'exited';
      container.uptime_seconds = 0;
    } else {
      throw new Error(`Unknown action: ${action}`);
    }

    return {
      success: true,
      container_id: containerId,
      action: action,
      new_status: container.status,
      message: `Container '${containerId}' ${action}ed successfully`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get namespace isolation details
 * @param {string} containerId - Container ID
 * @returns {Object} Namespace details
 */
function getNamespaceIsolation(containerId) {
  try {
    if (!containersDatabase[containerId]) {
      throw new Error(`Container '${containerId}' not found`);
    }

    return {
      container_id: containerId,
      isolation_provided: {
        processes: 'PID namespace - isolated process tree',
        network: 'Network namespace - isolated network interfaces',
        filesystem: 'Mount namespace - isolated filesystem mounts',
        ipc: 'IPC namespace - isolated message queues and semaphores',
        hostname: 'UTS namespace - isolated hostname and domain name',
        users: 'User namespace - isolated user IDs'
      },
      security_benefits: [
        'Containers cannot see or affect host processes',
        'Each container has its own network stack',
        'Filesystem changes are isolated',
        'No cross-container IPC interference'
      ]
    };
  } catch (error) {
    return { error: error.message };
  }
}

module.exports = {
  getInfo,
  getTest,
  listContainers,
  getContainerDetails,
  getContainerStats,
  listNamespaces,
  getCgroupsConfig,
  controlContainer,
  getNamespaceIsolation
};
